680	func checkProvidersDefined() error {
681		var count int
682	
683		var errBuilder strings.Builder
684	
685		bitbucketAPITokenComplete := bitbucketAPITokenDefined()
686	
687		for provider := range enabledProviderAuth {
688			switch provider {
689			case providerNameBitBucketAPIToken:
690				if bitbucketAPITokenComplete {
691					count++
692				}
693			case providerNameBitBucketOAuth:
694				// Only count if the API OAuthToken method isn't already complete.
695				if bitbucketOAuthDefined() && !bitbucketAPITokenComplete {
696					count++
697				}
698			default:
699				n, err := checkProvider(provider)
700				count += n
701	
702				if err != nil {
703					errBuilder.WriteString(err.Error())
704				}
705			}
706		}
707	
708		if errBuilder.Len() > 0 {
709			return errors.New(errBuilder.String())
710		}
711	
712		if count == 0 {
713			return errors.New("no providers defined")
714		}
715	
716		return nil
717	}
