    22		envTelegramBotToken        = "SOBA_TELEGRAM_BOT_TOKEN"
    23		envTelegramChatID          = "SOBA_TELEGRAM_CHAT_ID"
    24		envSobaNotifyOnFailureOnly = "SOBA_NOTIFY_ON_FAILURE_ONLY"
    25	
    26		titleBackupsSucceeded = "🚀 soba backups succeeded"
    27		titleBackupsErrors    = "️⚠️ soba backups completed with errors"
    28		titleBackupsFailed    = "️🚨 soba backups failed"
    29	)
    30	
    31	func backupStatusTitle(succeeded, failed int) string {
    32		switch {
    33		case succeeded > 0 && failed == 0:
    34			return titleBackupsSucceeded
    35		case failed > 0 && succeeded > 0:
    36			return titleBackupsErrors
    37		default:
    38			return titleBackupsFailed
    39		}
    40	}
