    42	func getResultsErrors(results BackupResults) []errors.E {
    43		var errs []errors.E
    44	
    45		if results.Results == nil {
    46			return nil
    47		}
    48	
    49		for _, providerResults := range *results.Results {
    50			if providerResults.Results.Error != nil {
    51				errs = append(errs, providerResults.Results.Error)
    52			}
    53		}
    54	
    55		return errs
    56	}
    57	
    58	func notify(backupResults BackupResults, succeeded int, failed int) {
    59		// optimistic create retryable http client
    60		errs := getResultsErrors(backupResults)
    61	
    62		// Check if we should only notify on failure
    63		notifyOnFailureOnly := envTrue(envSobaNotifyOnFailureOnly)
    64	
    65		// Skip notifications if success-only and no failures
    66		if notifyOnFailureOnly && failed == 0 {
    67			logger.Println("skipping notification (no failures)")
    68	
    69			return
    70		}
    71	
    72		webHookURL := os.Getenv(envSobaWebHookURL)
    73		if webHookURL != "" {
    74			err := sendWebhook(httpClient, sobaTime{
    75				Time: time.Now(),
    76				f:    time.RFC3339,
    77			}, backupResults, os.Getenv(envSobaWebHookURL), os.Getenv(envSobaWebHookFormat))
    78			if err != nil {
    79				logger.Printf("error sending webhook: %s", err)
    80			} else {
    81				logger.Println("webhook sent")
    82			}
    83		}
    84	
    85		ntfyURL := os.Getenv(envSobaNtfyURL)
    86		if ntfyURL != "" {
    87			sendNtfy(httpClient, ntfyURL, succeeded, failed, errs)
    88		}
    89	
    90		slackChannelID := os.Getenv(envSlackChannelID)
    91		if slackChannelID != "" {
    92			sendSlackMessage(slackChannelID, succeeded, failed, errs)
    93		}
    94	
    95		telegramBotToken := os.Getenv(envTelegramBotToken)
    96		telegramChatID := os.Getenv(envTelegramChatID)
    97	
    98		if telegramBotToken != "" && telegramChatID != "" {
    99			sendTelegramMessage(httpClient, telegramBotToken, telegramChatID, succeeded, failed, errs)
   100		}
   101	}
   102	
   103	func sendTelegramMessage(hc *retryablehttp.Client, botToken, chatID string, succeeded, failed int, errs []errors.E) {
   104		text := backupStatusTitle(succeeded, failed)
   105	
   106		text += fmt.Sprintf("\ncompleted: %d, failed: %d",
   107			succeeded, failed)
   108	
   109		if len(errs) > 0 && errs[0] != nil {
   110			text = fmt.Sprintf("%s\nerror: %s", text, errs[0].Error())
   111		}
   112	
   113		apiURL := "https://api.telegram.org/bot" + botToken + "/sendMessage?chat_id=" +
   114			chatID + "&text=" + url.QueryEscape(text)
   115	
   116		req, err := retryablehttp.NewRequest(http.MethodPost, apiURL, nil)
   117		if err != nil {
   118			logger.Printf("telegram failed to create request: %v", err)
   119	
   120			return
   121		}
   122	
   123		req.Header.Add("Content-Type", "application/json")
   124	
   125		// Build a dedicated client with the logger disabled — the Telegram URL
   126		// contains the bot token in its path, and the shared retryablehttp logger
   127		// would otherwise leak it at debug log level. retryablehttp clients are
   128		// non-copyable (sync.Once), so construct a fresh one.
   129		tc := retryablehttp.NewClient()
   130		if hc != nil && hc.HTTPClient != nil {
   131			tc.HTTPClient = hc.HTTPClient
   132			tc.RetryMax = hc.RetryMax
   133			tc.RetryWaitMin = hc.RetryWaitMin
   134			tc.RetryWaitMax = hc.RetryWaitMax
   135		}
   136	
   137		tc.Logger = nil
   138	
   139		resp, err := tc.Do(req)
   140		if err != nil {
   141			logger.Printf("telegram failed to send api request - error: %s", err)
   142	
   143			return
   144		}
   145	
   146		defer resp.Body.Close()
   147	
   148		_, err = io.ReadAll(resp.Body)
   149		if err != nil {
   150			logger.Printf("telegram failed to read response: %v", err)
   151	
   152			return
   153		}
   154	
   155		if resp.StatusCode != http.StatusOK {
   156			// Do not log response body — Telegram error responses can echo
   157			// chat_id and other metadata that is sensitive in shared deployments.
   158			logger.Printf("telegram failed to send message - code [%d]", resp.StatusCode)
   159	
   160			return
   161		}
   162	
   163		logger.Printf("telegram message successfully sent to chat id %s", chatID)
   164	}
   165	
   166	func sendNtfy(hc *retryablehttp.Client, nURL string, succeeded, failed int, errs []errors.E) {
   167		nu, err := url.Parse(nURL)
   168		if err != nil {
   169			logger.Printf("ntfy failed to parse url: %v", err)
   170	
   171			return
   172		}
   173	
   174		var req *retryablehttp.Request
   175	
   176		msg := fmt.Sprintf("completed: %d, failed: %d",
   177			succeeded, failed)
   178	
   179		if len(errs) > 0 && errs[0] != nil {
   180			msg = fmt.Sprintf("%s\nerror: %s", msg, errs[0].Error())
   181		}
   182	
   183		req, err = retryablehttp.NewRequest(http.MethodPost, nu.String(),
   184			strings.NewReader(msg))
   185		if err != nil {
   186			logger.Printf("ntfy failed to create request: %v", err)
   187	
   188			return
   189		}
   190	
   191		req.Header.Set("Title", backupStatusTitle(succeeded, failed))
   192	
   193		req.Header.Set("Tags", "soba,backup,git")
   194	
   195		resp, err := hc.Do(req)
   196		if err != nil {
   197			logger.Printf("ntfy request failed: %s", err)
   198	
   199			return
   200		}
   201	
   202		defer resp.Body.Close()
   203	
   204		logger.Println("ntfy publish sent")
   205	}
   206	
   207	func sendSlackMessage(slackChannelID string, succeeded, failed int, errs []errors.E) {
   208		errorMsgs := make([]string, 0)
   209	
   210		for _, err := range errs {
   211			if err != nil {
   212				errorMsgs = append(errorMsgs, err.Error())
   213			}
   214		}
   215	
   216		title := backupStatusTitle(succeeded, failed)
   217	
   218		attachment := slack.Attachment{
   219			Pretext: fmt.Sprintf("succeeded: %d, failed: %d", succeeded, failed),
   220			Text:    strings.Join(errorMsgs, "\n"),
   221		}
   222	
   223		api := slack.New(os.Getenv(envSlackAPIToken))
   224	
   225		channelID, timestamp, err := api.PostMessage(
   226			slackChannelID,
   227			slack.MsgOptionText(title, false),
   228			slack.MsgOptionAttachments(attachment),
   229			slack.MsgOptionAsUser(true),
   230		)
   231		if err != nil {
   232			logger.Println(err.Error())
   233	
   234			return
   235		}
   236	
   237		logger.Printf("slack message successfully sent to channel %s at %s", channelID, timestamp)
   238	}
