func removeContents(dir string) error {
	d, err := os.Open(filepath.Clean(dir))
	if err != nil {
		return fmt.Errorf("removeContents: %w", err)
	}

	defer func() {
		if err = d.Close(); err != nil {
			panic(err)
		}
	}()

	names, err := d.Readdirnames(-1)
	if err != nil {
		return fmt.Errorf("removeContents %w", err)
	}

	for _, name := range names {
		if err = os.RemoveAll(filepath.Clean(filepath.Join(dir, name))); err != nil {
			return fmt.Errorf("removeContents %w", err)
		}
	}

	return nil
}

func preflight() {
	var err error

	// prepare clean backup directory
	bud := os.Getenv(envGitBackupDir)

	// if path not provided, create one
	if bud == "" {
		bud, err = os.MkdirTemp(os.TempDir(), "sobabackup-*")
		if err != nil {
			panic(err)
		}

		_ = os.Setenv(envGitBackupDir, bud)

		return
	}

	_, err = os.Stat(filepath.Clean(bud))
	if os.IsNotExist(err) {
		if err = os.MkdirAll(filepath.Clean(bud), 0o700); err != nil {
			panic(err)
		}

		return
	}

	// clean out existing backup directory
	if err = removeContents(bud); err != nil {
		panic(err)
	}
}

